import{_ as e,c as t,o as d,a2 as o}from"./chunks/framework.DdOM6S6U.js";const w=JSON.parse('{"title":"SidebarContent (ue-sidebar-content)","description":"","frontmatter":{"sidebarPos":3,"sidebarTitle":"Sidebar Content"},"headers":[],"relativePath":"guide/components/layouts/sidebar-content.md","filePath":"guide/components/layouts/sidebar-content.md","lastUpdated":1777448653000}'),r={name:"guide/components/layouts/sidebar-content.md"},a=o('<h1 id="sidebarcontent-ue-sidebar-content" tabindex="-1">SidebarContent (<code>ue-sidebar-content</code>) <a class="header-anchor" href="#sidebarcontent-ue-sidebar-content" aria-label="Permalink to &quot;SidebarContent (`ue-sidebar-content`)&quot;">​</a></h1><p><code>SidebarContent</code> is an internal wrapper that sits between <a href="./sidebar"><code>Sidebar</code></a> and <a href="./sidebar-drawer-content"><code>SidebarDrawerContent</code></a>. Its responsibilities are:</p><ol><li><strong>Rendering the drawer</strong> — passes all sidebar state props down to <code>ue-sidebar-drawer-content</code>.</li><li><strong>Resize handle</strong> — adds an 8 px drag strip between the drawer and the main content area so users can resize the sidebar width.</li><li><strong>Secondary / content drawers</strong> — conditionally mounts additional <code>v-navigation-drawer</code> instances when <code>options.contentDrawer</code> or <code>secondaryOptions</code> are configured.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This is an internal component. You do not use it directly.</p></div><h2 id="resize-handle" tabindex="-1">Resize handle <a class="header-anchor" href="#resize-handle" aria-label="Permalink to &quot;Resize handle&quot;">​</a></h2><p>The resize handle is only shown when all of these are true:</p><ul><li>Sidebar is not in rail mode (<code>!rail</code>)</li><li>Sidebar is open (<code>status === true</code>)</li><li>Not in temporary (overlay) mode (<code>!effectiveTemporary</code>)</li><li>Screen is desktop size (<code>$vuetify.display.lgAndUp</code>)</li></ul><p>The handle is 8 px wide and uses <code>cursor: col-resize</code>. It highlights in <code>rgba(primary, 0.4)</code> on hover or while dragging. Dragging emits <code>resize-start</code> with the <code>mousedown</code> event, which is handled by <code>useSidebar</code>.</p><p>The handle&#39;s <code>left</code> (or <code>right</code> in right-to-left layouts) position tracks the current drawer <code>width</code> in px:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>left: {width}px   (ltr sidebar)</span></span>\n<span class="line"><span>right: {width}px  (rtl sidebar, sidebarLocation === &#39;right&#39;)</span></span></code></pre></div><h2 id="secondary-drawers" tabindex="-1">Secondary drawers <a class="header-anchor" href="#secondary-drawers" aria-label="Permalink to &quot;Secondary drawers&quot;">​</a></h2><p>Two optional <code>v-navigation-drawer</code> instances are mounted when their configuration objects exist:</p><table><thead><tr><th>Condition</th><th>Description</th></tr></thead><tbody><tr><td><code>options.contentDrawer?.exists</code></td><td>A content-panel drawer, max-width 15%, location driven by <code>options.location</code></td></tr><tr><td><code>secondaryOptions?.exists</code></td><td>A secondary navigation drawer at <code>secondaryOptions.location</code></td></tr></tbody></table><p>Both are pass-through — their content is not managed by this component.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code></td><td><code>Array</code></td><td>Yes</td><td>Forwarded to <code>ue-sidebar-drawer-content</code></td></tr><tr><td><code>profileMenu</code></td><td><code>Array</code></td><td>No</td><td>Forwarded to <code>ue-sidebar-drawer-content</code></td></tr><tr><td><code>miniSymbol</code></td><td><code>String|Object</code></td><td>No</td><td>Forwarded to <code>ue-sidebar-drawer-content</code></td></tr><tr><td><code>profileMenuOpen</code></td><td><code>Boolean</code></td><td>No</td><td>Two-way bound with <code>ue-sidebar-drawer-content</code></td></tr><tr><td><code>status</code></td><td><code>Boolean</code></td><td>Yes</td><td>Drawer open/closed state</td></tr><tr><td><code>rail</code></td><td><code>Boolean</code></td><td>Yes</td><td>Rail (icon-only) mode</td></tr><tr><td><code>isHoverable</code></td><td><code>Boolean</code></td><td>Yes</td><td>Vuetify expand-on-hover</td></tr><tr><td><code>hideIcons</code></td><td><code>Boolean</code></td><td>Yes</td><td>Text-only navigation mode</td></tr><tr><td><code>options</code></td><td><code>Object</code></td><td>Yes</td><td>Sidebar config object (location, railWidth, contentDrawer, etc.)</td></tr><tr><td><code>width</code></td><td><code>Number|String</code></td><td>Yes</td><td>Drawer width in px</td></tr><tr><td><code>effectivePersistent</code></td><td><code>Boolean</code></td><td>Yes</td><td>Vuetify persistent prop</td></tr><tr><td><code>effectivePermanent</code></td><td><code>Boolean</code></td><td>Yes</td><td>Vuetify permanent prop</td></tr><tr><td><code>effectiveTemporary</code></td><td><code>Boolean</code></td><td>No</td><td>Vuetify temporary (overlay) prop</td></tr><tr><td><code>railManual</code></td><td><code>Boolean</code></td><td>Yes</td><td>Whether rail was set manually by the user</td></tr><tr><td><code>secondaryOptions</code></td><td><code>Object</code></td><td>No</td><td>Config for the secondary drawer</td></tr><tr><td><code>isResizing</code></td><td><code>Boolean</code></td><td>No</td><td>Adds <code>ue-sidebar-resize-active</code> class to the handle</td></tr><tr><td><code>sidebarLocation</code></td><td><code>String</code></td><td>No</td><td><code>&#39;left&#39;</code> or <code>&#39;right&#39;</code>; controls handle position</td></tr></tbody></table><h2 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h2><table><thead><tr><th>Event</th><th>Description</th></tr></thead><tbody><tr><td><code>update:status</code></td><td>Forwarded from <code>ue-sidebar-drawer-content</code></td></tr><tr><td><code>update:profileMenuOpen</code></td><td>Forwarded from <code>ue-sidebar-drawer-content</code></td></tr><tr><td><code>activate-menu</code></td><td>Forwarded from <code>ue-sidebar-drawer-content</code></td></tr><tr><td><code>rail-toggle</code></td><td>Forwarded from <code>ue-sidebar-drawer-content</code></td></tr><tr><td><code>resize-start</code></td><td>Emitted on resize handle <code>mousedown</code></td></tr></tbody></table><h2 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h2><table><thead><tr><th>Slot</th><th>Description</th></tr></thead><tbody><tr><td><code>bottom</code></td><td>Passed through to <code>ue-sidebar-drawer-content</code></td></tr></tbody></table>',20),n=[a];function c(i,s,l,h,p,b){return d(),t("div",null,n)}const m=e(r,[["render",c]]);export{w as __pageData,m as default};
